            color: #ffffff;
        }

        .btn-number:hover {
            background-color: #4c4c4c;
        }

        .btn-operator {
            background-color: #f0c74d;
            color: #1e1e1e;
        }

        .btn-operator:hover {
            background-color: #e5b33d;
        }

        .btn-clear, .btn-equal {
            background-color: #a1887f;
            color: #ffffff;
        }

