<div class="calculator">
    <input type="text" id="display" readonly>
    <div class="keys">
        <button class="btn-clear" onclick="clearDisplay()">C</button>
        <button class="btn-operator" onclick="deleteLast()">DEL</button>
        <button class="btn-operator" onclick="appendOperator('/')">/</button>
        <button class="btn-operator" onclick="appendOperator('*')">×</button>

        <button class="btn-number" onclick="appendNumber('7')">7</button>
        <button class="btn-number" onclick="appendNumber('8')">8</button>
        <button class="btn-number" onclick="appendNumber('9')">9</button>
        <button class="btn-operator" onclick="appendOperator('-')">-</button>

        <button class="btn-number" onclick="appendNumber('4')">4</button>
        <button class="btn-number" onclick="appendNumber('5')">5</button>
        <button class="btn-number" onclick="appendNumber('6')">6</button>
        <button class="btn-operator" onclick="appendOperator('+')">+</button>

        <button class="btn-number" onclick="appendNumber('1')">1</button>
        <button class="btn-number" onclick="appendNumber('2')">2</button>
        <button class="btn-number" onclick="appendNumber('3')">3</button>
        <button class="btn-operator" onclick="appendNumber('.')">.</button>

        <button class="btn-number" onclick="appendNumber('0')">0</button>
        <button class="btn-number" onclick="appendNumber('00')">00</button>
        <button class="btn-equal" onclick="calculate()">=</button>
    </div>
</div>

<script>
    let currentInput = "";
    const display = document.getElementById('display');

    function appendNumber(number) {
        if (currentInput === "Error") {
            currentInput = "";
        }
        currentInput += number;
        updateDisplay();
    }

    function appendOperator(operator) {
        if (currentInput === "Error") return;
        const lastChar = currentInput.slice(-1);
        if (['+', '-', '*', '/'].includes(lastChar)) {
            currentInput = currentInput.slice(0, -1) + operator;
        } else {
            currentInput += operator;
        }
        updateDisplay();
    }

    function clearDisplay() {
        currentInput = "";
        updateDisplay();
    }

    function deleteLast() {
        if (currentInput === "Error") {
            clearDisplay();
            return;
        }
        currentInput = currentInput.slice(0, -1);
        updateDisplay();
    }

    function calculate() {
        try {
            if (currentInput === "") return;

            // Replace '×' and '÷' with standard operators for JS evaluation
            let expression = currentInput.replace(/×/g, '*').replace(/÷/g, '/');
            let result = eval(expression);

            // Handle floating point precision issues
            if (!Number.isInteger(result)) {
                result = result.toFixed(8).replace(/\.?0+$/, "");
            }

            currentInput = result.toString();
        } catch (error) {
            currentInput = "Error";
        }
        updateDisplay();
    }

    function updateDisplay() {
        display.value = currentInput;
    }
</script>

</body>
